mapper.select:
select

from pa_change_log p
where id = #{id,jdbcType=BIGINT}

mapper.sql:
select

,u.manager_num
from pa_change_log p
left join sys_user u on u.user_id = p.operator_id

    ${params.dataScope}

        and log_type = #{logType}


        and operator_name like concat('%', #{operatorName}, '%')


        and p.create_time >= #{startTime}


        and p.create_time <= #{endTime}


order by p.create_time desc

mapper.insert:
insert into pa_change_log
( subject, operate_type, log_type
, config_before, config_update, log_content
, operator_id, operator_name, create_time)
values ( #{subject,jdbcType=VARCHAR}, #{operateType,jdbcType=VARCHAR}
       , #{logType,jdbcType=VARCHAR}
       , #{configBefore,jdbcType=LONGVARCHAR}, #{configUpdate,jdbcType=LONGVARCHAR}, #{logContent,jdbcType=VARCHAR}
       , #{operatorId,jdbcType=BIGINT}, #{operatorName,jdbcType=VARCHAR}, #{createTime,jdbcType=TIMESTAMP})
